<script setup lang="ts">
import {computed,ref,onMounted,watch} from 'vue';import FocusShare from './FocusShare.vue';import {focusApi,duration,localDate} from './api';
const shareOpen=ref(false);
const props=defineProps<{data:any}>(),emit=defineEmits<{manual:[record?:any]}>();
const from=ref(localDate(new Date(new Date().getFullYear(),new Date().getMonth(),1))),to=ref(props.data.today),period=ref('daily'),report=ref<any>(null),error=ref(''),busy=ref(false),showTasks=ref(true),records=ref<any>({records:[],page:1,last_page:1,total:0});
async function load(){busy.value=true;try{[report.value,records.value]=await Promise.all([focusApi(`report?from=${from.value}&to=${to.value}`),focusApi(`records?from=${from.value}&to=${to.value}&page=1`)]);error.value='';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function recordPage(page:number){try{records.value=await focusApi(`records?from=${from.value}&to=${to.value}&page=${page}`);}catch(e:any){error.value=e.message;}}
onMounted(load);watch(()=>props.data.sessions,load);
const bars=computed(()=>{const rows:Record<string,number>={};for(const [date,seconds]of Object.entries(report.value?.daily||{})){let key=date;if(period.value==='monthly')key=date.slice(0,7);if(period.value==='yearly')key=date.slice(0,4);if(period.value==='weekly'){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));key=localDate(d);}rows[key]=(rows[key]||0)+Number(seconds);}return Object.entries(rows);});
const highest=computed(()=>Math.max(1,...bars.value.map(([,n])=>n))),days=computed(()=>report.value?Object.entries(report.value.daily).filter(([,n])=>Number(n)>=report.value.goal_seconds).length:0);
const projectRows=computed(()=>Object.entries(report.value?.projects||{}).map(([id,seconds])=>({name:props.data.projects.find((p:any)=>p.id===Number(id))?.name||'Tasks / removed project',seconds:Number(seconds)})));
</script>
<template><div class="ft-toolbar"><form @submit.prevent="load" class="ft-inline"><label>From<input v-model="from" type="date" required></label><label>To<input v-model="to" type="date" :min="from" required></label><button class="ft-primary" :disabled="busy">{{busy?'Loading…':'Update report'}}</button></form><button :disabled="!report||busy" @click="shareOpen=true">Share report</button><button @click="emit('manual')">+ Add focus record</button></div><p v-if="error" role="alert">{{error}}</p><template v-if="report"><div class="ft-stats"><article><small>Focused today</small><strong>{{duration(data.summary.seconds)}}</strong><small>{{data.summary.completed}} tasks completed</small></article><article><small>This week</small><strong>{{duration(data.week_summary?.seconds||0)}}</strong><small>{{data.week_summary?.completed||0}} tasks completed</small></article><article><small>Lifetime focus</small><strong>{{duration(data.lifetime_seconds||0)}}</strong></article><article><small>Lifetime completed</small><strong>{{data.lifetime_completed||0}}</strong></article></div><div class="ft-stats"><article><small>Focus time</small><strong>{{duration(report.seconds)}}</strong></article><article><small>Completed tasks</small><strong>{{report.completed}}</strong></article><article><small>Goal reached</small><strong>{{days}} days</strong></article><article><small>Daily focus goal</small><strong>{{duration(report.goal_seconds)}}</strong></article></div>
<article class="ft-panel"><div class="ft-heading"><div><h3>Focus over time</h3><p class="ft-muted">Includes manual records; breaks are excluded.</p></div><select v-model="period"><option v-for="p in ['daily','weekly','monthly','yearly']">{{p}}</option></select></div><div v-if="bars.length" class="ft-chart"><div v-for="[date,seconds] in bars" :title="duration(seconds)" class="ft-chart-column"><span>{{duration(seconds)}}</span><div :style="{height:Math.max(3,seconds/highest*155)+'px'}"></div><small>{{date}}</small></div></div><p v-else class="ft-empty">Complete your first focus session to see your progress.</p><p class="ft-muted">Highest: {{duration(highest===1?0:highest)}} · Average per active period: {{duration(bars.length?report.seconds/bars.length:0)}}</p></article>
<div class="ft-two"><article class="ft-panel"><h3>Project distribution</h3><div v-for="row in projectRows" class="ft-report-row"><span>{{row.name}}</span><strong>{{duration(row.seconds)}}</strong></div><p v-if="!projectRows.length" class="ft-muted">No recorded focus time.</p></article><article class="ft-panel"><h3>Focus by hour</h3><div class="ft-heatmap"><span v-for="(seconds,hour) in report.hours" :style="{opacity:seconds?.35+.65*seconds/Math.max(...report.hours):.22}" :title="`${hour}:00 · ${duration(seconds)}`">{{hour}}</span></div><p class="ft-muted">Hours follow {{data.settings.timezone}}.</p></article></div>
<article class="ft-panel"><h3>Daily goal calendar</h3><div class="ft-calendar"><div v-for="(seconds,date) in report.daily" :class="{reached:Number(seconds)>=report.goal_seconds}"><small>{{date}}</small><strong>{{duration(Number(seconds))}}</strong><span>{{Number(seconds)>=report.goal_seconds?'Goal reached':'Keep going'}}</span></div></div></article>
<article class="ft-panel"><label class="ft-check"><input v-model="showTasks" type="checkbox">Show recent focus records</label><div v-if="showTasks" class="ft-table-scroll"><table><thead><tr><th>Task</th><th>Started</th><th>Focus time</th><th>Source</th></tr></thead><tbody><tr v-for="session in records.records||[]"><td>{{session.task_title||'Removed task'}}</td><td>{{new Date(session.started_at).toLocaleString()}}</td><td>{{duration(session.elapsed_seconds)}}</td><td>{{session.manual?'Manual record':'Timer'}} <button v-if="session.manual" @click="emit('manual',session)">Edit</button></td></tr></tbody></table><footer class="ft-pagination"><small>{{records.total||0}} records ? Page {{records.page||1}} of {{records.last_page||1}}</small><div><button :disabled="!records.page||records.page===1" @click="recordPage(records.page-1)">Previous</button><button :disabled="!records.last_page||records.page===records.last_page" @click="recordPage(records.page+1)">Next</button></div></footer></div></article></template><FocusShare v-if="shareOpen&&report" title="Focus progress" :lines="[from+' to '+to,'Focus time: '+duration(report.seconds),'Completed tasks: '+report.completed,'Daily goal reached: '+days+' days',...projectRows.map(row=>row.name+': '+duration(row.seconds))]" @close="shareOpen=false"/></template>
